<?php
$rows=[]; try{$rows=Database::query("SELECT s.*,a.name admin_name,u.name target_current_name,b.name branch_name FROM security_impersonation_sessions s JOIN users a ON a.id=s.system_admin_user_id LEFT JOIN users u ON u.id=s.target_user_id LEFT JOIN branches b ON b.id=s.target_branch_id ORDER BY s.started_at DESC LIMIT 150")->fetchAll();}catch(Throwable $e){Security::reportException($e,'impersonation_history');}
?>
<section class="page-heading"><div><span class="eyebrow">AUDIT TRAIL</span><h1>Impersonation History</h1><p>Records every time System Admin entered an Owner or Branch account.</p></div></section>
<section class="card table-card"><div class="card-header"><div><h2>Recent Account Sessions</h2><p>Latest 150 sessions.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Started</th><th>System Admin</th><th>Viewed Account</th><th>Role / Branch</th><th>Ended</th><th>Reason</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e(date('M j, Y • g:i A',strtotime($r['started_at']))) ?></td><td><?= e($r['admin_name']) ?></td><td><strong><?= e($r['target_name']) ?></strong></td><td><?= e(role_label($r['target_role'])) ?><?= $r['branch_name']?' • '.e($r['branch_name']):'' ?></td><td><?= $r['ended_at']?e(date('M j, Y • g:i A',strtotime($r['ended_at']))):'<span class="status-pill available">Active</span>' ?></td><td><?= e($r['ended_reason']?:'—') ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state small"><strong>No impersonation history yet.</strong></div></td></tr><?php endif;?></tbody></table></div></section>
